from common import task

# 1 (dev) if/elif chain -> registry
task("rf-payment-strategies", "refactoring",
     "payments.process() is a growing if/elif chain. Refactor it so new payment methods can be added by registering "
     "a handler (payments.register(name, fn)) without editing process(). Behaviour for card, paypal and voucher must "
     "not change, including the error for unknown methods.",
     {"payments.py": "def process(method, amount):\n    if amount <= 0:\n        raise ValueError('amount must be positive')\n    if method == 'card':\n        fee = round(amount * 0.029 + 0.30, 2)\n        return {'method': 'card', 'charged': round(amount + fee, 2), 'fee': fee}\n    elif method == 'paypal':\n        fee = round(amount * 0.034, 2)\n        return {'method': 'paypal', 'charged': round(amount + fee, 2), 'fee': fee}\n    elif method == 'voucher':\n        return {'method': 'voucher', 'charged': 0.0, 'fee': 0.0}\n    else:\n        raise ValueError(f'unknown method {method}')\n"},
     {"hidden_t.py": "import inspect, payments\nfrom payments import process, register\nassert process('card',100)=={'method':'card','charged':103.2,'fee':3.2}\nassert process('paypal',50)=={'method':'paypal','charged':51.7,'fee':1.7}\nassert process('voucher',9)=={'method':'voucher','charged':0.0,'fee':0.0}\nfor bad in (('card',0),('crypto',5)):\n    try:\n        process(*bad); raise SystemExit('accepted')\n    except ValueError as e: pass\ntry: process('crypto',5)\nexcept ValueError as e: assert 'unknown method crypto' in str(e)\nsrc=inspect.getsource(process)\nassert \"'paypal'\" not in src and \"'card'\" not in src, 'process still names methods'\nregister('bank', lambda amount: {'method':'bank','charged':amount,'fee':0.0})\nassert process('bank',10)=={'method':'bank','charged':10,'fee':0.0}\nprint('ok')\n"},
     "python3 hidden_t.py",
     {"payments.py": "HANDLERS = {}\n\ndef register(name, fn):\n    HANDLERS[name] = fn\n\ndef process(method, amount):\n    if amount <= 0:\n        raise ValueError('amount must be positive')\n    if method not in HANDLERS:\n        raise ValueError(f'unknown method {method}')\n    return HANDLERS[method](amount)\n\ndef _card(amount):\n    fee = round(amount * 0.029 + 0.30, 2)\n    return {'method': 'card', 'charged': round(amount + fee, 2), 'fee': fee}\n\ndef _paypal(amount):\n    fee = round(amount * 0.034, 2)\n    return {'method': 'paypal', 'charged': round(amount + fee, 2), 'fee': fee}\n\nregister('card', _card)\nregister('paypal', _paypal)\nregister('voucher', lambda amount: {'method': 'voucher', 'charged': 0.0, 'fee': 0.0})\n"},
     split="dev")

# 2 circular import that breaks depending on import order
task("rf-break-cycle", "refactoring",
     "Importing orders before customers works, but importing customers first crashes with an ImportError (circular "
     "import). Restructure the modules so both import orders work, without changing the public functions "
     "customers.lifetime_value(cid) and orders.orders_for(cid) or their results.",
     {"customers.py": "from orders import orders_for\n\nCUSTOMERS = {1: 'Ann', 2: 'Bo'}\n\ndef name(cid):\n    return CUSTOMERS[cid]\n\ndef lifetime_value(cid):\n    return sum(o['total'] for o in orders_for(cid))\n",
      "orders.py": "from customers import name\n\nORDERS = [{'cid': 1, 'total': 10}, {'cid': 2, 'total': 5}, {'cid': 1, 'total': 7}]\n\ndef orders_for(cid):\n    return [dict(o, customer=name(o['cid'])) for o in ORDERS if o['cid'] == cid]\n"},
     {"hidden_t.sh": "set -e\npython3 -c 'import customers, orders; assert customers.lifetime_value(1)==17 and orders.orders_for(2)==[{\"cid\":2,\"total\":5,\"customer\":\"Bo\"}]'\npython3 -c 'import orders, customers; assert customers.lifetime_value(2)==5 and orders.orders_for(1)[1][\"customer\"]==\"Ann\"'\npython3 -c 'import customers; assert customers.lifetime_value(1)==17'\npython3 -c 'import orders; assert len(orders.orders_for(1))==2'\necho ok\n"},
     "bash hidden_t.sh",
     {"customers.py": "CUSTOMERS = {1: 'Ann', 2: 'Bo'}\n\ndef name(cid):\n    return CUSTOMERS[cid]\n\ndef lifetime_value(cid):\n    from orders import orders_for\n    return sum(o['total'] for o in orders_for(cid))\n",
      "orders.py": "ORDERS = [{'cid': 1, 'total': 10}, {'cid': 2, 'total': 5}, {'cid': 1, 'total': 7}]\n\ndef orders_for(cid):\n    from customers import name\n    return [dict(o, customer=name(o['cid'])) for o in ORDERS if o['cid'] == cid]\n"})

# 3 duplicated, inconsistent validation -> one source of truth following the spec
task("rf-dedupe-validation", "refactoring",
     "signup.py, profile.py and invite.py each validate emails and phone numbers with their own slightly different "
     "copies. Move validation into one module validation.py (functions valid_email and valid_phone) used by all "
     "three, following RULES.md exactly, so all three accept and reject the same inputs.",
     {"RULES.md": "# Validation rules\n\n- Email: one '@'; local part 1-64 chars of letters, digits and . _ + -, not starting or ending with '.', no '..'; domain has at least one '.', labels of letters, digits and '-', not starting or ending with '-'; top-level label at least 2 letters. Case-insensitive; surrounding spaces are ignored.\n- Phone: optional leading '+', then 8 to 15 digits; spaces, '-' and parentheses are allowed between digits and ignored.\n",
      "signup.py": "import re\n\ndef signup(email, phone):\n    if not re.match(r'^[^@]+@[^@]+\\.[a-z]{2,}$', email.strip().lower()):\n        return 'bad email'\n    digits = re.sub(r'[ -]', '', phone)\n    if not re.match(r'^\\+?\\d{8,15}$', digits):\n        return 'bad phone'\n    return 'ok'\n",
      "profile.py": "def update(email, phone):\n    if '@' not in email or '.' not in email.split('@')[-1]:\n        return 'bad email'\n    d = ''.join(c for c in phone if c.isdigit())\n    if not 8 <= len(d) <= 15:\n        return 'bad phone'\n    return 'ok'\n",
      "invite.py": "import re\nEMAIL = re.compile(r'^[\\w.+-]+@[\\w-]+(\\.[\\w-]+)+$')\n\ndef invite(email):\n    return 'ok' if EMAIL.match(email) else 'bad email'\n"},
     {"hidden_t.py": "import inspect, signup, profile, invite, validation\ngood=['a@b.co',' Ann.Lee+x@Mail-1.example.ORG ','x_y@d.io']\nbad=['a@b','a..b@c.io','.a@b.io','a.@b.io','a@-b.io','a@b-.io','a@b.c','a@b@c.io','a b@c.io','@b.io','a@b.i1','x'*65+'@b.io']\nfor e in good:\n    assert validation.valid_email(e) and signup.signup(e,'+44 20 7946 0958')=='ok' and profile.update(e,'0123456789')=='ok' and invite.invite(e)=='ok', e\nfor e in bad:\n    assert not validation.valid_email(e) and signup.signup(e,'12345678')=='bad email' and profile.update(e,'12345678')=='bad email' and invite.invite(e)=='bad email', e\npgood=['+1 (555) 123-4567','12345678','+123456789012345']\npbad=['1234567','+1234567890123456','12a45678','++12345678','(555) 12-34','']\nfor p in pgood: assert validation.valid_phone(p) and signup.signup('a@b.co',p)=='ok' and profile.update('a@b.co',p)=='ok', p\nfor p in pbad: assert not validation.valid_phone(p) and signup.signup('a@b.co',p)=='bad phone' and profile.update('a@b.co',p)=='bad phone', p\nfor m in (signup, profile, invite):\n    src=inspect.getsource(m); assert 'import re' not in src and 'validation' in src, m.__name__\nprint('ok')\n"},
     "python3 hidden_t.py",
     {"validation.py": "import re\n\n_LABEL = re.compile(r'^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?$')\n_LOCAL = re.compile(r'^[a-z0-9_+-](?:[a-z0-9._+-]*[a-z0-9_+-])?$')\n\ndef valid_email(email):\n    e = email.strip().lower()\n    if e.count('@') != 1:\n        return False\n    local, domain = e.split('@')\n    if not 1 <= len(local) <= 64 or not _LOCAL.match(local) or '..' in local:\n        return False\n    labels = domain.split('.')\n    if len(labels) < 2 or not all(_LABEL.match(l) for l in labels):\n        return False\n    return bool(re.match(r'^[a-z]{2,}$', labels[-1]))\n\ndef valid_phone(phone):\n    p = phone.strip()\n    if not re.match(r'^\\+?[\\d\\s()\\-]+$', p) or p.count('+') > 1:\n        return False\n    digits = re.sub(r'\\D', '', p)\n    return 8 <= len(digits) <= 15\n",
      "signup.py": "from validation import valid_email, valid_phone\n\ndef signup(email, phone):\n    if not valid_email(email):\n        return 'bad email'\n    if not valid_phone(phone):\n        return 'bad phone'\n    return 'ok'\n",
      "profile.py": "from validation import valid_email, valid_phone\n\ndef update(email, phone):\n    if not valid_email(email):\n        return 'bad email'\n    if not valid_phone(phone):\n        return 'bad phone'\n    return 'ok'\n",
      "invite.py": "from validation import valid_email\n\ndef invite(email):\n    return 'ok' if valid_email(email) else 'bad email'\n"})

# 4 module-level global state -> instances, old API kept
task("rf-globals-to-instance", "refactoring",
     "metrics.py keeps its counters in module globals, so two components can't keep separate metrics and tests "
     "leak into each other. Introduce a Metrics class (incr, observe, snapshot, reset) so separate instances are "
     "independent. Keep the existing module-level functions working exactly as before, backed by one default "
     "instance (metrics.default).",
     {"metrics.py": "COUNTS = {}\nOBS = {}\n\ndef incr(name, by=1):\n    COUNTS[name] = COUNTS.get(name, 0) + by\n\ndef observe(name, value):\n    OBS.setdefault(name, []).append(value)\n\ndef snapshot():\n    return {'counts': dict(COUNTS), 'means': {k: sum(v) / len(v) for k, v in OBS.items()}}\n\ndef reset():\n    COUNTS.clear(); OBS.clear()\n",
      "server.py": "import metrics\n\ndef handle(path):\n    metrics.incr('requests')\n    metrics.observe('latency_ms', 12 if path == '/' else 40)\n    return 200\n"},
     {"hidden_t.py": "import metrics, server\nfrom metrics import Metrics\na,b=Metrics(),Metrics()\na.incr('x'); a.incr('x',2); b.incr('x'); a.observe('t',1); a.observe('t',3)\nassert a.snapshot()=={'counts':{'x':3},'means':{'t':2.0}} and b.snapshot()=={'counts':{'x':1},'means':{}}\na.reset(); assert a.snapshot()=={'counts':{},'means':{}} and b.snapshot()['counts']=={'x':1}\nmetrics.reset(); server.handle('/'); server.handle('/x')\nassert metrics.snapshot()=={'counts':{'requests':2},'means':{'latency_ms':26.0}}\nassert metrics.default.snapshot()==metrics.snapshot() and isinstance(metrics.default, Metrics)\nassert a.snapshot()['counts']=={}\nprint('ok')\n"},
     "python3 hidden_t.py",
     {"metrics.py": "class Metrics:\n    def __init__(self):\n        self.counts, self.obs = {}, {}\n\n    def incr(self, name, by=1):\n        self.counts[name] = self.counts.get(name, 0) + by\n\n    def observe(self, name, value):\n        self.obs.setdefault(name, []).append(value)\n\n    def snapshot(self):\n        return {'counts': dict(self.counts), 'means': {k: sum(v) / len(v) for k, v in self.obs.items()}}\n\n    def reset(self):\n        self.counts.clear(); self.obs.clear()\n\ndefault = Metrics()\nincr, observe, snapshot, reset = default.incr, default.observe, default.snapshot, default.reset\n"})

# 5 god function -> small functions, behaviour table preserved
task("rf-split-invoice", "refactoring",
     "invoice.total() is one long function nobody dares touch. Split it into small, named functions (no function "
     "longer than 20 lines, measured from def to its last line) without changing any result, including errors.",
     {"invoice.py": "def total(lines, country, coupon=None, member=False):\n    if not lines:\n        raise ValueError('empty invoice')\n    subtotal = 0.0\n    for l in lines:\n        if l['qty'] <= 0:\n            raise ValueError('bad qty')\n        price = l['price']\n        if l.get('category') == 'book':\n            price = price * 0.95\n        subtotal += price * l['qty']\n    discount = 0.0\n    if coupon == 'SAVE10':\n        discount = subtotal * 0.10\n    elif coupon == 'FLAT5':\n        discount = min(5.0, subtotal)\n    elif coupon is not None:\n        raise ValueError('unknown coupon')\n    if member:\n        discount += (subtotal - discount) * 0.02\n    net = subtotal - discount\n    if country == 'UK':\n        tax = net * 0.20\n    elif country == 'DE':\n        tax = net * 0.19\n    elif country == 'US':\n        tax = 0.0\n    else:\n        raise ValueError('unsupported country')\n    shipping = 0.0 if net >= 50 else 4.99\n    if country == 'US' and net < 50:\n        shipping = 6.99\n    return round(net + tax + shipping, 2)\n"},
     {"hidden_t.py": "import ast, inspect, invoice\nfrom invoice import total\nL=[{'price':20,'qty':2},{'price':10,'qty':1,'category':'book'}]\ncases=[((L,'UK'),),((L,'DE','SAVE10'),),((L,'US','FLAT5',True),),(([{'price':5,'qty':1}],'US'),),(([{'price':5,'qty':1}],'UK',None,True),),((L*3,'DE','FLAT5',True),)]\nexp=[64.39, 58.0, 50.6, 11.99, 10.87, 167.35]\nfor c,e in zip(cases,exp):\n    assert total(*c[0])==e, (c, total(*c[0]), e)\nfor bad in (([],'UK'),([{'price':1,'qty':0}],'UK'),(L,'FR'),(L,'UK','NOPE')):\n    try:\n        total(*bad); raise SystemExit('accepted')\n    except ValueError: pass\ntree=ast.parse(inspect.getsource(invoice))\nlong=[(n.name, n.end_lineno-n.lineno+1) for n in ast.walk(tree) if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef)) and n.end_lineno-n.lineno+1>20]\nassert not long, long\nassert len([n for n in ast.walk(tree) if isinstance(n, ast.FunctionDef)])>=4\nprint('ok')\n"},
     "python3 hidden_t.py",
     {"invoice.py": "def _subtotal(lines):\n    if not lines:\n        raise ValueError('empty invoice')\n    s = 0.0\n    for l in lines:\n        if l['qty'] <= 0:\n            raise ValueError('bad qty')\n        price = l['price'] * 0.95 if l.get('category') == 'book' else l['price']\n        s += price * l['qty']\n    return s\n\ndef _discount(subtotal, coupon, member):\n    if coupon == 'SAVE10':\n        d = subtotal * 0.10\n    elif coupon == 'FLAT5':\n        d = min(5.0, subtotal)\n    elif coupon is not None:\n        raise ValueError('unknown coupon')\n    else:\n        d = 0.0\n    if member:\n        d += (subtotal - d) * 0.02\n    return d\n\nTAX = {'UK': 0.20, 'DE': 0.19, 'US': 0.0}\n\ndef _tax(net, country):\n    if country not in TAX:\n        raise ValueError('unsupported country')\n    return net * TAX[country]\n\ndef _shipping(net, country):\n    if net >= 50:\n        return 0.0\n    return 6.99 if country == 'US' else 4.99\n\ndef total(lines, country, coupon=None, member=False):\n    subtotal = _subtotal(lines)\n    net = subtotal - _discount(subtotal, coupon, member)\n    tax = _tax(net, country)\n    return round(net + tax + _shipping(net, country), 2)\n"})

# 6 exporters behind a registry discovered by decorator
task("rf-exporter-registry", "refactoring",
     "export.export(rows, fmt) hard-codes every format. Refactor to a registry: formats register themselves with a "
     "decorator @exporter('name'); export() looks them up and raises ValueError listing the available formats for an "
     "unknown one. CSV and JSON output must stay byte-identical. A new format must be addable from another module "
     "without editing export.py.",
     {"export.py": "import csv, io, json\n\ndef export(rows, fmt):\n    if fmt == 'csv':\n        buf = io.StringIO()\n        w = csv.DictWriter(buf, fieldnames=list(rows[0]) if rows else [])\n        w.writeheader(); w.writerows(rows)\n        return buf.getvalue()\n    if fmt == 'json':\n        return json.dumps(rows, indent=2, sort_keys=True)\n    raise ValueError('unknown format')\n"},
     {"hidden_t.py": "import export\nfrom export import export as ex, exporter\nrows=[{'b':1,'a':'x,y'},{'b':2,'a':'z'}]\nassert ex(rows,'csv')=='b,a\\r\\n1,\"x,y\"\\r\\n2,z\\r\\n' and ex([],'csv')=='\\r\\n'\nimport json; assert ex(rows,'json')==json.dumps(rows, indent=2, sort_keys=True)\n@exporter('tsv')\ndef tsv(rows):\n    return '\\n'.join('\\t'.join(str(v) for v in r.values()) for r in rows)\nassert ex(rows,'tsv')=='1\\tx,y\\n2\\tz'\ntry:\n    ex(rows,'xml'); raise SystemExit('accepted')\nexcept ValueError as e:\n    assert 'csv' in str(e) and 'json' in str(e) and 'tsv' in str(e), str(e)\nimport inspect; src=inspect.getsource(export.export)\nassert \"'csv'\" not in src and \"'json'\" not in src\nprint('ok')\n"},
     "python3 hidden_t.py",
     {"export.py": "import csv, io, json\n\nEXPORTERS = {}\n\ndef exporter(name):\n    def deco(fn):\n        EXPORTERS[name] = fn\n        return fn\n    return deco\n\ndef export(rows, fmt):\n    if fmt not in EXPORTERS:\n        raise ValueError(f'unknown format {fmt}; available: {\", \".join(sorted(EXPORTERS))}')\n    return EXPORTERS[fmt](rows)\n\n@exporter('csv')\ndef _csv(rows):\n    buf = io.StringIO()\n    w = csv.DictWriter(buf, fieldnames=list(rows[0]) if rows else [])\n    w.writeheader(); w.writerows(rows)\n    return buf.getvalue()\n\n@exporter('json')\ndef _json(rows):\n    return json.dumps(rows, indent=2, sort_keys=True)\n"})

# 7 sync client -> shared core with sync and async front ends
task("rf-sync-async-client", "refactoring",
     "Add an async API next to the existing synchronous one: AsyncClient with the same methods as Client "
     "(get_user, list_users) but awaitable, using transport.async_fetch. Request building and response parsing "
     "(including the error mapping) must live in one place used by both clients, not be duplicated. The sync "
     "client must behave exactly as before.",
     {"transport.py": "import asyncio\nDATA = {'/users/1': (200, {'id': 1, 'name': 'Ann'}), '/users': (200, [{'id': 1, 'name': 'Ann'}, {'id': 2, 'name': 'Bo'}]), '/users/9': (404, {'error': 'no such user'})}\n\ndef fetch(path):\n    return DATA.get(path, (500, {'error': 'boom'}))\n\nasync def async_fetch(path):\n    await asyncio.sleep(0)\n    return fetch(path)\n",
      "client.py": "import transport\n\nclass NotFound(Exception):\n    pass\n\nclass ApiError(Exception):\n    pass\n\nclass Client:\n    def get_user(self, uid):\n        status, body = transport.fetch(f'/users/{int(uid)}')\n        if status == 404:\n            raise NotFound(body['error'])\n        if status != 200:\n            raise ApiError(f'{status}: {body.get(\"error\")}')\n        return body\n\n    def list_users(self):\n        status, body = transport.fetch('/users')\n        if status == 404:\n            raise NotFound(body['error'])\n        if status != 200:\n            raise ApiError(f'{status}: {body.get(\"error\")}')\n        return [u['name'] for u in body]\n"},
     {"hidden_t.py": "import asyncio, inspect, client, transport\nfrom client import Client, AsyncClient, NotFound, ApiError\nc=Client(); assert c.get_user(1)=={'id':1,'name':'Ann'} and c.list_users()==['Ann','Bo']\nasync def main():\n    a=AsyncClient(); assert await a.get_user('1')=={'id':1,'name':'Ann'} and await a.list_users()==['Ann','Bo']\n    try:\n        await a.get_user(9); raise SystemExit('no raise')\n    except NotFound as e: assert 'no such user' in str(e)\n    try:\n        await a.get_user(5); raise SystemExit('no raise')\n    except ApiError as e: assert str(e)=='500: boom'\nasyncio.run(main())\nfor bad,exc in ((9,NotFound),(5,ApiError)):\n    try:\n        c.get_user(bad); raise SystemExit('no raise')\n    except exc: pass\nsrc=inspect.getsource(client)\nassert src.count('status == 404')+src.count('status==404')<=1 and src.count('raise NotFound(')<=1, 'error mapping duplicated'\nassert inspect.iscoroutinefunction(AsyncClient.get_user)\nprint('ok')\n"},
     "python3 hidden_t.py",
     {"client.py": "import transport\n\nclass NotFound(Exception):\n    pass\n\nclass ApiError(Exception):\n    pass\n\ndef _user_path(uid):\n    return f'/users/{int(uid)}'\n\ndef _parse(status, body):\n    if status == 404:\n        raise NotFound(body['error'])\n    if status != 200:\n        raise ApiError(f'{status}: {body.get(\"error\")}')\n    return body\n\ndef _names(body):\n    return [u['name'] for u in body]\n\nclass Client:\n    def get_user(self, uid):\n        return _parse(*transport.fetch(_user_path(uid)))\n\n    def list_users(self):\n        return _names(_parse(*transport.fetch('/users')))\n\nclass AsyncClient:\n    async def get_user(self, uid):\n        return _parse(*await transport.async_fetch(_user_path(uid)))\n\n    async def list_users(self):\n        return _names(_parse(*await transport.async_fetch('/users')))\n"})
